#include <cstdlib>
#include <cstdint>
#include <vector>

static inline int mandel(double cr, double ci) {
    double zr = 0.0, zi = 0.0;
    for (int i = 0; i < 50; ++i) {
        double zr2 = zr * zr - zi * zi + cr;
        double zi2 = 2.0 * zr * zi + ci;
        zr = zr2;
        zi = zi2;
        if (zr * zr + zi * zi > 4.0) return 0;
    }
    return 1;
}

int main(int argc, char** argv) {
    if (argc < 2) return 0;
    int N = std::atoi(argv[1]);
    if (N <= 0) return 0;

    std::printf("P4\n%d %d\n", N, N);

    const double scale_x = 3.0 / N;
    const double scale_y = 3.0 / N;

    std::vector<unsigned char> row((N + 7) / 8);

    for (int y = 0; y < N; ++y) {
        double ci = (y * scale_y) - 1.5;
        std::fill(row.begin(), row.end(), 0);

        for (int x = 0; x < N; ++x) {
            double cr = (x * scale_x) - 2.0;
            if (mandel(cr, ci)) {
                row[x >> 3] |= (unsigned char)(0x80u >> (x & 7));
            }
        }

        std::fwrite(row.data(), 1, row.size(), stdout);
    }

    return 0;
}
